<template><main class="world-page" v-if="world"><section class="world-header"><button class="world-cover" :aria-label="`预览 ${world.name} 的封面`" @click="previewCover"><img v-if="cover&&!coverFailed" :src="cover" :alt="world.name" @error="coverFailed=true" /><span v-else class="cover-initial">{{ world.name.slice(0,1) }}</span><span class="world-id">ID {{ world.novel_id }}</span></button><div class="world-info"><span class="world-type">世界设定</span><h1>{{ world.name }}</h1><nuxt-link class="world-author" :to="`/users/${world.author_id||world.creator_id}`"><ReaderAvatar :src="world.auther_avatar||world.avatar_url" />{{ world.user_name||world.author_name||'佚名' }}</nuxt-link><p class="world-updated">最近更新 {{ formatDate(world.update_time) }} · {{ worldOutlines.length }} 个大纲 · {{ worldVocabs.length }} 个词条</p><p class="world-description">{{ world.content||'作者尚未填写世界简介。' }}</p><BookSupport :book="world" @tipped="refreshFans" @account-change="onAccountChange" /><nuxt-link v-if="isCreator" class="edit-world" :to="`/write/edit/${world.novel_id}?worldId=${world.world_id}`">编辑设定 →</nuxt-link></div></section>
  <div class="world-content"><div class="world-tabs" role="tablist" aria-label="世界内容"><button v-for="tab in tabs" :key="tab.id" role="tab" :aria-selected="activeTab===tab.id" :class="{active:activeTab===tab.id}" @click="activeTab=tab.id">{{ tab.label }}</button><nuxt-link :to="`/world/relations/${world.novel_id}`">关系网 ↗</nuxt-link></div>
    <section v-show="activeTab==='settings'" class="world-settings"><div class="outline-header"><h2>世界大纲</h2><span>{{ worldOutlines.length }} 篇</span></div><div v-if="worldOutlines.length" class="outline-grid"><nuxt-link v-for="(outline,index) in worldOutlines" :key="outline.article_id" :to="`/article/${outline.article_id}`"><span>{{ String(index+1).padStart(2,'0') }}</span><strong>{{ outline.title }}</strong><small>{{ formatDate(outline.update_time) }}</small></nuxt-link></div><p v-else class="world-empty">这个世界尚未发布大纲。</p><WorldVocabularyBrowser :articles="worldVocabs" :novel-id="world.novel_id" /></section>
    <section v-show="activeTab==='works'" class="associated-works"><p v-if="associatedError" class="world-error" role="alert">{{ associatedError }} <button @click="reloadAssociated" :disabled="associatedLoading">重试</button></p><div class="works-grid"><WorkCard v-for="work in assoNovels" :key="work.novel_id" :work="work" /></div><p v-if="!assoNovels.length&&!associatedError" class="world-empty">尚未关联其他作品。</p></section>
    <section v-if="activeTab==='comments'"><MangaCommentPanel inline :visible="true" :novel-id="world.novel_id" :work-author-id="world.author_id||world.creator_id" :anchor-id="commentAnchor" /></section><section v-if="activeTab==='fans'"><NovelFansList ref="fansList" :novelId="world.novel_id" :limit="6" /></section>
  </div></main></template>
<script>
import { loadPublicWorld,worldImage } from '~/utils/reader-world'
import { readingCommentId } from '~/utils/reader-comment-links'
import { readingHead,bookSchema } from '~/utils/reading-seo'
import { readingToken } from '~/plugins/api/reading'
import BookSupport from '~/components/read/BookSupport.vue'
import ReaderAvatar from '~/components/read/ReaderAvatar.vue'
import WorldVocabularyBrowser from '~/components/read/WorldVocabularyBrowser.vue'
import WorkCard from '~/components/read/WorkCard.vue'
import MangaCommentPanel from '~/components/manga/MangaCommentPanel.vue'
import NovelFansList from '~/components/NovelFansList.vue'
export default {
 components:{BookSupport,ReaderAvatar,WorldVocabularyBrowser,WorkCard,MangaCommentPanel,NovelFansList},asyncData:loadPublicWorld,
 data:()=>({world:null,worldOutlines:[],worldVocabs:[],assoNovels:[],associatedError:'',associatedLoading:false,associatedVersion:0,activeTab:'settings',userInfo:null,profileVersion:0,coverFailed:false,tabs:[{id:'settings',label:'世界设定'},{id:'works',label:'关联作品'},{id:'comments',label:'评论'},{id:'fans',label:'粉丝榜'}]}),
 head(){return readingHead({title:this.world?`${this.world.name} - 世界设定 - 原木社区`:'世界设定 - 原木社区',description:this.world&&this.world.content,path:`/world/${this.world?this.world.novel_id:this.$route.params.id}`,image:this.world&&this.world.picUrl,type:'book',schema:this.world?bookSchema(this.world,`/world/${this.world.novel_id}`):undefined})},
 computed:{commentAnchor(){return readingCommentId(this.$route.query)},cover(){return worldImage(this.world&&this.world.picUrl)},isCreator(){return !!(this.userInfo&&this.world&&Number(this.userInfo.user_id)===Number(this.world.creator_id||this.world.author_id))}},
 watch:{commentAnchor(value){if(value)this.activeTab='comments'},'world.novel_id'(){this.associatedVersion++;this.coverFailed=false;this.activeTab=this.commentAnchor?'comments':'settings';this.loadProfile()}},mounted(){if(this.commentAnchor)this.activeTab='comments';this.loadProfile()},beforeDestroy(){this.profileVersion++;this.associatedVersion++},
 methods:{previewCover(){if(this.cover&&this.$preview)this.$preview([this.cover],0)},formatDate(value){const date=new Date(value);return value&&!Number.isNaN(date.getTime())?date.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}):'时间未记录'},
 async loadProfile(){const version=++this.profileVersion,token=readingToken();this.userInfo=null;if(!token)return;try{const user=await this.$api.reader.profile();if(version===this.profileVersion&&token===readingToken())this.userInfo=user}catch(_){/* Public world remains readable without an authenticated profile. */}},
 onAccountChange(){this.loadProfile();this.refreshFans()},refreshFans(){if(this.$refs.fansList)this.$refs.fansList.getFansList()},
 async reloadAssociated(){if(this.associatedLoading)return;const version=++this.associatedVersion,id=this.world.world_id;this.associatedLoading=true;try{const works=await this.$api.reader.worldWorks(id);if(version!==this.associatedVersion||id!==this.world.world_id)return;this.assoNovels=Array.isArray(works)?works:[];this.associatedError=''}catch(error){if(version===this.associatedVersion)this.associatedError=error.message||'关联作品加载失败'}finally{if(version===this.associatedVersion)this.associatedLoading=false}}
 }
}
</script>
<style scoped>.world-page{max-width:1280px;margin:0 auto;padding:32px 40px 60px;box-sizing:border-box}.world-header{display:flex;gap:34px;padding:32px;border:1px solid #e7e2d8;border-radius:14px;background:linear-gradient(135deg,#faf6ed,#fff 65%);align-items:flex-start}.world-cover{position:relative;flex-shrink:0;width:170px;aspect-ratio:3/4;padding:0;overflow:hidden;border-radius:9px;border:1px solid #dfd8c8;background:#e3e8d2;cursor:zoom-in}.world-cover>img{display:block;width:100%;height:100%;object-fit:cover}.cover-initial{font-size:60px;color:#a0ad79}.world-id{position:absolute;bottom:0;left:0;right:0;padding:8px 12px;font-size:11px;letter-spacing:2px;background:#faf9f0ed;color:#928365;text-align:left}.world-info{min-width:0;flex:1}.world-type{display:inline-block;font-size:11px;letter-spacing:2px;color:#8d9c64;background:#edf1e1;padding:5px 10px;border-radius:5px}.world-info h1{font-size:30px;line-height:1.4;font-weight:600;color:#6a5840;margin:10px 0 16px;overflow-wrap:anywhere}.world-author{display:inline-flex;align-items:center;gap:10px;font-size:13px;color:#927c5f;text-decoration:none}.world-author .reader-avatar{width:30px;height:30px}.world-updated{font-size:12px;color:#b09f84;margin:16px 0}.world-description{font-size:14px;color:#9b896e;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere}.edit-world{display:inline-block;font-size:12px;color:#8b9c5c;margin-top:16px;text-decoration:none}.world-content{background:#fff;border:1px solid #e7e2d8;border-radius:12px;margin-top:24px;padding:24px 30px}.world-tabs{display:flex;gap:24px;flex-wrap:wrap;align-items:center;border-bottom:1px solid #ebe5da;margin-bottom:28px;padding-bottom:14px}.world-tabs button{padding:6px 0;background:none;border:0;font:inherit;font-size:14px;color:#a08d70;cursor:pointer;position:relative}.world-tabs .active{color:#7f9257}.world-tabs .active:after{content:'';position:absolute;left:0;right:0;height:2px;bottom:-15px;background:#8ea362}.world-tabs>a{margin-left:auto;color:#829456;font-size:12px;text-decoration:none}.outline-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.outline-header h2{font-size:17px;color:#857052}.outline-header span{font-size:12px;color:#afa086}.outline-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-bottom:32px}.outline-grid a{display:flex;align-items:center;gap:12px;padding:16px;border:1px solid #e7e0d4;border-radius:7px;background:#faf9f6;text-decoration:none;min-width:0}.outline-grid span{font-size:12px;color:#c0b398}.outline-grid strong{font-size:13px;font-weight:500;color:#867153;min-width:0;overflow-wrap:anywhere}.outline-grid small{font-size:10px;color:#b7a88f;margin-left:auto;white-space:nowrap}.works-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.world-empty{font-size:13px;padding:30px;text-align:center;color:#aa9a80}.world-error{font-size:13px;color:#b86951;line-height:1.8}.world-error button{border:0;background:none;text-decoration:underline;color:inherit;cursor:pointer}a:focus-visible,button:focus-visible{outline:2px solid #8c9f60;outline-offset:3px}@media(max-width:1000px){.world-page{padding:24px}.world-header{padding:26px;gap:24px}.world-cover{width:145px}.works-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.outline-grid{grid-template-columns:1fr}}@media(max-width:700px){.world-page{padding:20px 16px}.world-header{padding:20px;gap:16px}.world-cover{width:100px}.world-info h1{font-size:22px}.world-content{padding:20px}.world-author .reader-avatar{width:30px;height:30px}.world-updated{line-height:1.8}.world-tabs{gap:20px}.world-tabs>a{margin-left:0}.works-grid{grid-template-columns:1fr}.outline-grid small{display:none}}
</style>
